sys_variable_value.value:
(function execute(inputs, outputs) {
try {
    var r = new sn_ws.RESTMessageV2('global.Manage Depedent Info', 'add Dependent Info');
    //var body = JSON.parse(inputs.requestBody);
    var body = inputs.requestBody;
    //gs.info("111RC: body: " + JSON.stringify(body));
    r.setRequestBody(JSON.stringify(body));

    var response = r.execute();
    var responseBody = response.getBody();
    var httpStatus = response.getStatusCode();
} catch (ex) {
    var message = ex.message;
}

var responseObj = JSON.parse(responseBody);
//gs.info("111RC: resBody: " + JSON.stringify(responseObj));
var result = responseObj.result;
//gs.info("111RC: result: " + JSON.stringify(result));
if(httpStatus == 200 || httpStatus == 201){
    var status = "SUCCESS";
}
else
    status = "FAILURE";
 

//gs.info("111RC: message: " + JSON.stringify(result.depedentAdditionMessage));

outputs.message = result.depedentAdditionMessage;
outputs.status = status;


gs.info(responseBody);
})(inputs, outputs);

